// Safe SSH runner for Soul Pilates box (.200).
// - Decrypts server.rootPasswordEnc in-memory (never printed).
// - Asserts remote `hostname -I` contains 51.79.226.200 before running the payload.
// - Runs the command passed as argv[2]; prints stdout/stderr/exit code.
const { createDecipheriv, scryptSync } = require("node:crypto");
const { Client } = require("/opt/nxeon/node_modules/ssh2");

const TARGET_IP = "51.79.226.200";
const AUTH_SECRET = process.env.AUTH_SECRET;
const ENC = process.env.ROOT_PW_ENC;
const CMD = process.argv[2];
if (!AUTH_SECRET) throw new Error("AUTH_SECRET missing");
if (!ENC) throw new Error("ROOT_PW_ENC missing");
if (!CMD) throw new Error("No command given");

function deriveKey() {
  return scryptSync(AUTH_SECRET, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  const [ivB64, tagB64, dataB64] = enc.split(":");
  const decipher = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
  decipher.setAuthTag(Buffer.from(tagB64, "base64"));
  const dec = Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]);
  return dec.toString("utf8");
}

const password = decryptSecret(ENC);
if (!password) throw new Error("decrypt failed");

function exec(conn, command, timeoutMs = 300000) {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let stdout = "", stderr = "";
      const t = setTimeout(() => { try { stream.close(); } catch {} reject(new Error("timeout")); }, timeoutMs);
      stream.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); })
        .on("data", (d) => stdout += d.toString("utf8"))
        .stderr.on("data", (d) => stderr += d.toString("utf8"));
    });
  });
}

const conn = new Client();
conn.on("ready", async () => {
  try {
    const chk = await exec(conn, "hostname -I");
    if (!chk.stdout.split(/\s+/).includes(TARGET_IP)) {
      console.error("SAFETY ABORT: remote hostname -I does not contain " + TARGET_IP + " -> " + chk.stdout.trim());
      conn.end();
      process.exit(3);
    }
    const r = await exec(conn, CMD);
    process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write("\n[STDERR]\n" + r.stderr);
    console.log("\n[EXIT " + r.code + "]");
    conn.end();
    process.exit(r.code === 0 ? 0 : 1);
  } catch (e) {
    console.error("RUN ERROR: " + e.message);
    conn.end();
    process.exit(2);
  }
}).on("error", (e) => { console.error("SSH ERROR: " + e.message); process.exit(2); })
  .connect({ host: TARGET_IP, port: 22, username: "root", password, readyTimeout: 15000 });

