=====ssh200.mjs=====
// Safe SSH runner to the LIVE Soul Pilates box (.200).
// - Loads AUTH_SECRET + DATABASE_URL from /opt/nxeon/.env
// - Reads Server row cmsc9l72y000ghl7iyd87u5ja via Prisma, decrypts rootPasswordEnc
// - NEVER prints the plaintext password
// - Remote-side ASSERTS hostname -I contains 51.79.226.200 before running the payload
// Usage: node ssh200.mjs '<remote bash command>'
import { readFileSync } from "node:fs";
import { createDecipheriv, scryptSync } from "node:crypto";
import { Client } from "/opt/nxeon/node_modules/ssh2/lib/index.js";
import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client/index.js";

// --- load .env (minimal parser) ---
const env = {};
for (const line of readFileSync("/opt/nxeon/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m) {
    let v = m[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    env[m[1]] = v;
  }
}
process.env.DATABASE_URL = env.DATABASE_URL;

function deriveKey() {
  return scryptSync(env.AUTH_SECRET, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  const [ivB64, tagB64, dataB64] = enc.split(":");
  const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
  d.setAuthTag(Buffer.from(tagB64, "base64"));
  return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
}

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECT_IP = "51.79.226.200";
const payload = process.argv[2];
if (!payload) { console.error("no command"); process.exit(2); }

const prisma = new PrismaClient();
const server = await prisma.server.findUnique({
  where: { id: SERVER_ID },
  include: { dedicatedIp: true },
});
await prisma.$disconnect();
if (!server) { console.error("server row not found"); process.exit(3); }

const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
if (!password) { console.error("no root password"); process.exit(4); }

const host = server.dedicatedIp ? server.dedicatedIp.address : (env.PUBLIC_IP || EXPECT_IP);
const port = server.dedicatedIp ? 22 : Number(server.sshPort);

// Guard: the resolved host must be the expected live box.
if (host !== EXPECT_IP) { console.error("host mismatch, refusing:", host); process.exit(5); }

// Remote assertion wrapper: bail unless hostname -I contains .200.
const wrapped =
  `if ! hostname -I | grep -qw '${EXPECT_IP}'; then echo 'ASSERT_FAIL: not ${EXPECT_IP}' >&2; exit 9; fi\n` +
  payload;

const conn = new Client();
conn
  .on("ready", () => {
    conn.exec(wrapped, (err, stream) => {
      if (err) { console.error(err.message); process.exit(6); }
      stream
        .on("close", (code) => { conn.end(); process.exit(code || 0); })
        .on("data", (d) => process.stdout.write(d))
        .stderr.on("data", (d) => process.stderr.write(d));
    });
  })
  .on("error", (e) => { console.error("SSH error:", e.message); process.exit(7); })
  .connect({ host, port, username: "root", password, readyTimeout: 15000 });

