using System.Collections.Generic;
using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Entities;

public class ClassBlueprint : BaseEntity
{
    // ── Identity (existing) ──
    public string ClassName { get; set; } = null!;
    public string DifficultyLevel { get; set; } = "ALL_LEVELS"; // "BEGINNER", "INTERMEDIATE", "ADVANCED", "ALL_LEVELS"
    public string Format { get; set; } = "GROUP"; // "GROUP", "PRIVATE"
    public string FocusArea { get; set; } = "FULL_BODY";
    public int DurationMinutes { get; set; } = 60;

    public int DefaultCapacity { get; set; } = 10;

    // ── Customer Booking Portal — Rich Class Metadata ──
    public string? Description { get; set; }
    public List<string> Benefits { get; set; } = new();
    public List<string> GoodFor { get; set; } = new();
    public List<string> MuscleAreas { get; set; } = new();       // MuscleMapJS Muscle IDs e.g. ["abs", "gluteal", "hamstring"]
    public List<string> Tags { get; set; } = new();              // e.g. ["Posture", "Neck Relief", "Mobility"]
    public string? EquipmentType { get; set; }                   // "Reformer", "Wunda Chair", "Ladder Barrel"
                                                                 // ↑ Legacy singular name kept for backward compat.
                                                                 //   Populated from the FIRST entry of EquipmentTypes.

    /// <summary>
    /// Reference to the <see cref="Equipment"/> document chosen in the blueprint editor.
    /// Null on old blueprints that only have a free-text EquipmentType.
    /// When set, the booking portal shows the equipment's full image and description.
    /// Legacy singular FK kept for backward compat; populated from the FIRST entry of EquipmentIds.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? EquipmentId { get; set; }

    /// <summary>
    /// SPM-71 — A class blueprint may use more than one piece of equipment.
    /// Ordered list of <see cref="Equipment"/> document IDs (parallel to
    /// <see cref="EquipmentTypes"/>). The legacy singular <see cref="EquipmentId"/>
    /// is kept populated from the FIRST entry for backward compatibility.
    /// Defaults to an empty list so existing MongoDB documents (which only have
    /// the singular field) deserialize safely — callers treat a missing/empty
    /// list as <c>[EquipmentId]</c>.
    /// </summary>
    public List<string> EquipmentIds { get; set; } = new();

    /// <summary>
    /// SPM-71 — Ordered list of equipment display NAMES (parallel to
    /// <see cref="EquipmentIds"/>). This is the denormalised value copied onto
    /// <see cref="CalendarSession.EquipmentTypes"/> at materialisation time and
    /// used by the customer booking page for filtering and the equipment-image
    /// lookup. The legacy singular <see cref="EquipmentType"/> is kept populated
    /// from the FIRST entry for backward compatibility.
    /// Defaults to an empty list so existing MongoDB documents (which only have
    /// the singular field) deserialize safely — callers treat a missing/empty
    /// list as <c>[EquipmentType]</c>.
    /// </summary>
    public List<string> EquipmentTypes { get; set; } = new();

    public string? ImageUrl { get; set; }                        // Admin-uploaded hero image per class
    public bool IsFeatured { get; set; } = false;                // Show on public homepage "Our Classes" section

    // ── V2: Pricing (replaces all Product class types) ──
    // The single source of truth for walk-in/drop-in class pricing.
    // POS reads this instead of the now-deprecated Product class types.

    /// <summary>Walk-in / drop-in price for this class (VND). 0 = free.</summary>
    public decimal DropInPrice { get; set; }

    /// <summary>Tax rate applied to the drop-in price (percentage, 0–100). Default 0 (no tax).</summary>
    public decimal TaxRate { get; set; }

    // ── V2: Default Instructor ──

    /// <summary>The default instructor assigned to all materialised sessions unless overridden per-slot.</summary>
