    public string? DefaultInstructorName { get; set; }

    // ── V2: Weekly Schedule Slots (replaces RecurringScheduleRule) ──
    // Each slot defines a recurring day/time. Multiple slots per day allowed.
    // Save triggers materialisation — no "Publish" step.

    /// <summary>
    /// Inline weekly schedule. Each entry generates recurring <see cref="CalendarSession"/>
    /// rows via the materialiser. Replaces the separate RecurringScheduleRule entity.
    /// </summary>
    public List<WeeklySlot> WeeklySlots { get; set; } = new();

    // ── V2: Status ──

    /// <summary>Active blueprints materialise sessions and appear on the POS classes tab.</summary>
    public bool IsActive { get; set; } = true;

    /// <summary>Freelance class flag — sessions from this blueprint use freelance credit math.</summary>
    public bool IsFreelance { get; set; } = false;

    /// <summary>
    /// SPM-91 — Default public visibility for sessions materialised from this
    /// blueprint. When false, new sessions are created hidden from the public
    /// booking page (admins can still flip individual sessions public).
    /// Defaults to TRUE so existing MongoDB documents (missing the field)
    /// deserialize as PUBLIC.
    /// </summary>
    public bool DefaultIsPublic { get; set; } = true;

    // ── V2: Schedule Validity ──

    /// <summary>ISO "yyyy-MM-dd". Materialiser only creates sessions on or after this date. Null = immediate.</summary>
    public string? ValidFrom { get; set; }

    /// <summary>ISO "yyyy-MM-dd". Materialiser stops creating sessions after this date. Null = open-ended.</summary>
    public string? ValidTo { get; set; }

    // ── V2: Per-blueprint Exception Dates ──

    /// <summary>
    /// ISO "yyyy-MM-dd" dates to skip during materialisation (e.g., class-specific holidays
    /// or instructor vacations). Materialiser checks this before creating a session.
    /// </summary>
    public List<string> ExceptionDates { get; set; } = new();
}

