    public async Task<ClassDetailDto?> GetClassDetailAsync(string sessionId)
    {
        var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
        if (session is null) return null;

        // Load all confirmed attendances for this session.
        // SPM-79 — exclude RESCHEDULED: a booking moved to another session no longer
        // belongs on this roster. Also exclude RESERVED: those are transient checkout
        // holds (customer reached the payment step but hasn't completed/paid) that
        // auto-expire; showing them as roster "attendees" mislabels an abandoned
        // checkout as a confirmed booking and inflates the "X/Y booked" count.
        var attendances = await _attendances
            .Find(a => a.CalendarSessionId == sessionId
                && a.Status != "CANCELLED"
                && a.Status != "RESCHEDULED"
                && a.Status != "RESERVED")
            .SortBy(a => a.BookedAt)
            .ToListAsync();

        // Reverse-lookup: find any invoices linked to these attendances
        var attIds = attendances.Select(a => a.Id!).ToList();
        var invoiceLinkMap = new Dictionary<string, (string invoiceId, string invoiceNumber)>();
        var invoiceStatusMap = new Dictionary<string, (string status, decimal totalNet)>();
        if (attIds.Count > 0)
        {
            var linkedInvoices = await _invoices.Find(
                Builders<Invoice>.Filter.ElemMatch(
                    i => i.Lines,
                    Builders<InvoiceLine>.Filter.In(l => l.AttendanceId, attIds)
                )
            ).ToListAsync();
            foreach (var inv in linkedInvoices)
            {
                foreach (var line in inv.Lines.Where(l => !string.IsNullOrWhiteSpace(l.AttendanceId)))
                {
                    if (!invoiceLinkMap.ContainsKey(line.AttendanceId!))
                    {
                        invoiceLinkMap[line.AttendanceId!] = (inv.Id!, inv.InvoiceNumber);
                        invoiceStatusMap[line.AttendanceId!] = (inv.Status, inv.TotalNet);
                    }
                }
            }
        }

        // SPM-84 — NEW-client detection. A client is "NEW" when this session is
        // their first-ever non-cancelled attendance at the studio. We resolve the
        // earliest non-cancelled attendance per client across ALL sessions, then
        // flag the roster row whose attendance Id matches that earliest record.
        // FirstVisitDate on the Client entity is only populated by the historical
        // import (not on live bookings), so it is unreliable here — counting
        // attendances is the authoritative source.
        var rosterClientIds = attendances.Select(a => a.ClientId).Distinct().ToList();
        var firstAttendanceIdByClient = new Dictionary<string, string>();
        if (rosterClientIds.Count > 0)
        {
            var clientAttendances = await _attendances
                .Find(a => rosterClientIds.Contains(a.ClientId) && a.Status != "CANCELLED")
                .Project(a => new { a.Id, a.ClientId, a.BookedAt })
                .ToListAsync();

            foreach (var grp in clientAttendances.GroupBy(a => a.ClientId))
            {
                // Earliest by BookedAt, tie-broken by Id for determinism.
                var earliest = grp
                    .OrderBy(a => a.BookedAt)
                    .ThenBy(a => a.Id)
                    .First();
                firstAttendanceIdByClient[grp.Key] = earliest.Id!;
            }
        }

        // GUEST detection — a client with no linked CustomerAccount booked as a
        // guest (guest checkout or admin-created) and never finished creating an
        // account. One IN query resolves the set of roster clients that DO have an
        // account; everyone else on the roster is a guest.
        var accountClientIds = new HashSet<string>();
        if (rosterClientIds.Count > 0)
        {
            var withAccounts = await _accounts
                .Find(a => rosterClientIds.Contains(a.ClientId))
                .Project(a => a.ClientId)
                .ToListAsync();
            foreach (var cid in withAccounts)
                if (!string.IsNullOrEmpty(cid)) accountClientIds.Add(cid);
        }

        var attendeeDtos = attendances.Select(att =>
        {
            var paid = att.AmountPaid ?? 0m;
            var due = att.AmountDueAtStudio ?? 0m;

            // Use linked invoice status as source of truth — Attendance fields
            // may be stale when balance was settled via POS invoice-payment flow.
            if (invoiceStatusMap.TryGetValue(att.Id!, out var invStatus))
            {
                if (invStatus.status == "PAID")
                {
                    paid = invStatus.totalNet;
                    due = 0m;
                }
            }

            string payStatus;
            if (att.IsFreeClass) payStatus = "free";
            else if (att.PaymentMethod == "PACKAGE_CREDIT") payStatus = "package";
            else if (due <= 0) payStatus = "paid";
            else if (paid > 0 && due > 0) payStatus = "partial";
            else payStatus = "unpaid";

            // SPM-85 — roster-wide "missing payment" flag, mirroring the POS rule:
            // free classes and PACKAGE_CREDIT are settled; an outstanding balance
            // (computed "unpaid" or "partial") on an active attendance is unpaid.
            // NO_SHOW / LATE_CANCEL rows are not treated as collectable (CANCELLED
            // is already excluded from this roster query).
            var isActive = att.Status != "NO_SHOW" && att.Status != "LATE_CANCEL";
            var isUnpaid = isActive && (payStatus == "unpaid" || payStatus == "partial");

            // SPM-84 — first-ever non-cancelled attendance for this client.
            var isNew = firstAttendanceIdByClient.TryGetValue(att.ClientId, out var firstId)
                && firstId == att.Id;

            invoiceLinkMap.TryGetValue(att.Id!, out var invLink);

            return new ClassAttendeeDto
            {
                AttendanceId = att.Id!,
                ClientId = att.ClientId,
                ClientName = att.ClientName ?? "Unknown",
                ClientPhone = att.ClientPhone,
                ClientEmail = att.ClientEmail,
                BookingReference = att.BookingReference,
                Status = att.Status,
