    /// has no remaining active (non-cancelled) seats, restore Capacity to 1 so a
    /// freed 1-on-1 slot cannot be double-booked by two unrelated single bookers.
    /// </summary>
    private async Task RestorePrivateCapacityIfEmptyAsync(string sessionId)
    {
        var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
        if (session == null) return;
        if (session.Format != "PRIVATE" || session.Capacity <= 1) return;

        // Count seats still held by active (non-cancelled) attendances.
        var activeSeats = await _attendances
            .Find(a => a.CalendarSessionId == sessionId && a.Status != "CANCELLED")
            .ToListAsync();
        var heldSeats = activeSeats.Sum(a => Math.Max(1, a.Quantity));

        if (heldSeats <= 0)
        {
            await _sessions.UpdateOneAsync(
                s => s.Id == sessionId,
                Builders<CalendarSession>.Update.Set(s => s.Capacity, 1));
        }
    }

    /// <inheritdoc />
    public async Task<int> CleanupExpiredReservationsAsync(int expiryMinutes)
    {
        if (expiryMinutes <= 0) expiryMinutes = 15;
        var cutoff = DateTime.UtcNow.AddMinutes(-expiryMinutes);

        // Find all RESERVED attendances that are older than the cutoff.
        // Use ReservedAt when available, else fall back to BookedAt for
        // legacy rows that don't have the field yet.
        var expiredFilter = Builders<Attendance>.Filter.Eq(a => a.Status, "RESERVED") &
            (Builders<Attendance>.Filter.Lt(a => a.ReservedAt, cutoff) |
             (Builders<Attendance>.Filter.Eq(a => a.ReservedAt, (DateTime?)null) &
              Builders<Attendance>.Filter.Lt(a => a.BookedAt, cutoff)));

        var expired = await _attendances.Find(expiredFilter).ToListAsync();
        if (expired.Count == 0) return 0;

        var cleaned = 0;
        foreach (var att in expired)
        {
            // Release each one individually so the capacity bookkeeping is correct
            var released = await ReleaseReservationAsync(att.Id!);
            if (released) cleaned++;
        }

        return cleaned;
    }

