    /// <summary>
    /// Override a materialised session: reschedule, swap instructor, change capacity.
    /// The original session is mutated in-place with IsOverride = true.
    /// </summary>
    [HttpPatch("session/{id}/override")]
    [Authorize(Roles = "Admin,Manager,Receptionist,HeadInstructor,Instructor")]
    public async Task<IActionResult> OverrideSession(string id, [FromBody] OverrideSessionRequest request)
    {
        // SPM-91 — resolve the public-visibility intent. When the request omits
        // IsPublic (legacy clients), preserve the session's current value rather
        // than defaulting it on or off.
        var current = await _schedulingService.GetSessionByIdAsync(id);
        if (current is null) return NotFound(new { message = "Session not found." });

        var updated = new CalendarSession
        {
            InstructorId = request.InstructorId,
            InstructorName = request.InstructorName,
            ClassName = request.ClassName,
            FocusArea = request.FocusArea,
            DifficultyLevel = request.DifficultyLevel,
            Capacity = request.Capacity,
            StartTime = request.StartTime,
            EndTime = request.EndTime,
            Status = request.Status,
            IsPublic = request.IsPublic ?? current.IsPublic,
        };
        var success = await _schedulingService.OverrideSessionAsync(id, updated, request.Note);
        if (!success) return NotFound(new { message = "Session not found." });
        return Ok(new { message = "Session overridden." });
    }

