   Change an existing attendee's seat count in place (card cmskphkyx…).
   The backend guards the minimum of 1, the PRIVATE duo cap, and remaining
   capacity, and keeps the booked count + the attendee's credit / amount-due
   in lock-step — so a rejection surfaces the API's real message. */
async adjustAttendeeQty(attendanceId, newQty) {
  if (!this._sessionId) return;
  const n = Math.max(1, parseInt(newQty, 10) || 1);
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/session/${this._sessionId}/attendee/${attendanceId}/quantity`, {
      method: 'PATCH',
      headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' },
      body: JSON.stringify({ quantity: n }),
    });
    if (!r.ok) throw new Error(await this._readApiError(r));
    window.showToast?.(`Seats updated to ×${n}`, 'success');
    // Full refresh so the "X/Y booked" header + spots-remaining update too,
    // then sync any external calendar view (mirrors _addStudent).
    if (this._afterAttendanceUpdate && this._sessionId) await this._afterAttendanceUpdate(this._sessionId);
    this.refresh();
  } catch (err) {
    window.showToast?.(err.message || 'Failed to update seats', 'error');
  }
},

